$ErrorActionPreference = "Stop"`n$base = "http://localhost:8080/api"`n`nWrite-Host "=== Analyze API ===" -ForegroundColor Cyan`n$body = @{`n  schema = "FDM"`n  tableShortName = "f_ac_ctds_ldr_acct"`n  tableFullName = "FDM.f_ac_ctds_ldr_acct"`n  fieldName = "acct_no"`n  direction = "DOWNSTREAM"`n  maxDepth = 20`n} | ConvertTo-Json`n`n$result = Invoke-RestMethod -Uri ($base + "/impact/analyze") -Method Post -Body $body -ContentType "application/json"`n`nif ($result.data) { $d = $result.data } else { $d = $result }`n$nodes = if ($d.nodes) { $d.nodes } else { $d.graphInitialNodes }`n$edges = if ($d.edges) { $d.edges } else { $d.graphInitialEdges }`n`nWrite-Host ("Nodes count: " + $nodes.Count)`nWrite-Host ("Edges count: " + $edges.Count)`n`nWrite-Host ""`nWrite-Host "=== Target TRANSFORM nodes ===" -ForegroundColor Yellow`n$found = 0`nforeach ($n in $nodes) {`n  if ($n.nodeLevel -eq "TRANSFORM" -and $n.expression -and $n.expression.StartsWith("CASE WHEN T12.ACCT_NO IS NOT N")) {`n    $found++`n    Write-Host "Found node ID: " $n.id`n    $exprLen = [Math]::Min(120, $n.expression.Length)`n    Write-Host "Expression: " $n.expression.Substring(0, $exprLen)`n    Write-Host "  Input fields:"`n    $ic = 0`n    foreach ($e in $edges) {`n      if ($e.target -eq $n.id -and $e.edgeType -eq "INPUT_TO") {`n        $ic++`n        $r = if ($e.role) { $e.role } else { "value" }`n        $a = if ($e.sourceAlias) { $e.sourceAlias } else { "null" }`n        Write-Host ("    " + $ic + ". colKey=" + $e.source + ", role=" + $r + ", alias=" + $a)`n      }`n    }`n    Write-Host "  Total inputs: " $ic`n  }`n}`nif ($found -eq 0) {`n  Write-Host "Not found. Samples:" -ForegroundColor Red`n  $c=0`n  foreach ($n in $nodes) { if ($n.nodeLevel -eq "TRANSFORM" -and $c -lt 15) { Write-Host "  " $n.id " : " $n.expression.Substring(0,[Math]::Min(60,$n.expression.Length)); $c++ } }`n}`nWrite-Host ""`nWrite-Host "Total target nodes: " $found -ForegroundColor $(if($found){"Green"}else{"Red"})`n$result | ConvertTo-Json -Depth 20 | Out-File -FilePath "api-full.json"`nWrite-Host "Saved to api-full.json"